&lt;ActionGrid&gt;
  &lt;Settings&gt;
    &lt;Version&gt;5.27.0&lt;/Version&gt;
    &lt;Build&gt;5.27.144&lt;/Build&gt;
    &lt;CurrentContext&gt;ExportImport&lt;/CurrentContext&gt;
    &lt;ModuleId&gt;801&lt;/ModuleId&gt;
    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;;WITH Parametri AS (
    SELECT 
        [Initializari:ZileLucratoare_old(Anul=[GetOrSession:YearV], Luna=[GetOrSession:MonthV])] AS ZileLucratoare
)
SELECT
    a.Id,
    a.Marca,
    a.Nume,
    b.Salariu,
    a.TipNorma,
    p.ZileLucratoare,

    -- CROSS APPLY calcule pentru a evita repetițiile
    ca.OreLucrate,
    ca.SalBrutEfectiv,
    ca.TicheteTotale,
    ca.TotalBrut,
    ca.CAS,
    ca.CASS,
    ca.VenitNet,
    ca.BazaImpozabila,
    ca.ImpozitVenit,
    ca.SalariuNet

FROM app.Salariat a
LEFT JOIN app.NomGrilaSalarizare b
    ON a.Clasa = b.Clasa AND b.TipMediu = &#39;U&#39;
LEFT JOIN app.TSTichetMasa t
    ON t.Luna = a.Luna AND t.Anul = a.Anul
CROSS JOIN Parametri p

-- Calculam toate valorile &#238;ntr-un singur loc
CROSS APPLY (
    SELECT
        -------------------------------------------------------
        -- 1️⃣ Ore lucrate &#238;n funcție de norma &#215; zile lucrătoare
        -------------------------------------------------------
        (p.ZileLucratoare * a.TipNorma * 8) AS OreLucrate,

        -------------------------------------------------------
        -- 2️⃣ Salariul brut efectiv &#238;n funcție de ore lucrate
        --    (plată proporțională &#238;n funcție de norma și zile)
        -------------------------------------------------------
        ROUND(
            (b.Salariu / (p.ZileLucratoare * 8)) 
            * (p.ZileLucratoare * a.TipNorma * 8),
            0
        ) AS SalBrutEfectiv,

        -------------------------------------------------------
        -- 3️⃣ Tichetele de masă &#215; zile lucrătoare
        -------------------------------------------------------
        (t.Valoare * p.ZileLucratoare) AS TicheteTotale,

        -------------------------------------------------------
        -- 4️⃣ Total Brut = Salar Br + Tichete
        -------------------------------------------------------
        ROUND(
            (b.Salariu / (p.ZileLucratoare * 8)) 
            * (p.ZileLucratoare * a.TipNorma * 8),
            0
        ) 
        + (t.Valoare * p.ZileLucratoare)
        AS TotalBrut,

        -------------------------------------------------------
        -- 5️⃣ CAS = 25% &#215; Salariu Brut Efectiv
        -------------------------------------------------------
        ROUND(
            ROUND(
                (b.Salariu / (p.ZileLucratoare * 8)) 
                * (p.ZileLucratoare * a.TipNorma * 8),
                0
            ) * 0.25,
            0
        ) AS CAS,

        -------------------------------------------------------
        -- 6️⃣ CASS = 10% &#215; (Brut + Tichete)
        -------------------------------------------------------
        ROUND(
            (
                ROUND(
                    (b.Salariu / (p.ZileLucratoare * 8)) 
                    * (p.ZileLucratoare * a.TipNorma * 8),
                    0
                )
                + (t.Valoare * p.ZileLucratoare)
            ) * 0.10,
            0
        ) AS CASS,

        -------------------------------------------------------
        -- 7️⃣ Venit Net = Total Brut – CAS – CASS
        -------------------------------------------------------
        (
            ROUND(
                (b.Salariu / (p.ZileLucratoare * 8)) 
                * (p.ZileLucratoare * a.TipNorma * 8),
                0
            )
            + (t.Valoare * p.ZileLucratoare)
            - ROUND(
                ROUND(
                    (b.Salariu / (p.ZileLucratoare * 8)) 
                    * (p.ZileLucratoare * a.TipNorma * 8),
                    0
                ) * 0.25,
                0
            )
            - ROUND(
                (
                    ROUND(
                        (b.Salariu / (p.ZileLucratoare * 8)) 
                        * (p.ZileLucratoare * a.TipNorma * 8),
                        0
                    )
                    + (t.Valoare * p.ZileLucratoare)
                ) * 0.10,
                0
            )
        ) AS VenitNet,

        -------------------------------------------------------
        -- 8️⃣ Baza impozabilă (brut - CAS - CASS)
        -------------------------------------------------------
        (b.Salariu 
         - ROUND(b.Salariu * 0.25,0)
         - ROUND(b.Salariu * 0.10,0)
        ) AS BazaImpozabila,

        -------------------------------------------------------
        -- 9️⃣ Impozit (10% &#215; Baza impozabilă)
        -------------------------------------------------------
        ROUND(
            (
                b.Salariu 
                - ROUND(b.Salariu * 0.25,0)
                - ROUND(b.Salariu * 0.10,0)
            ) * 0.10,
            0
        ) AS ImpozitVenit,

        -------------------------------------------------------
        --  Salariu Net final
        -------------------------------------------------------
        (
            (b.Salariu 
             - ROUND(b.Salariu * 0.25,0)
             - ROUND(b.Salariu * 0.10,0))
            -
            ROUND(
                (
                    b.Salariu 
                    - ROUND(b.Salariu * 0.25,0)
                    - ROUND(b.Salariu * 0.10,0)
                ) * 0.10,
                0
            )
        ) AS SalariuNet

) ca

WHERE a.Luna = @Luna
  AND a.CodSucursala = @CodSucursala
  AND a.Anul = @Anul
ORDER BY a.Marca;
